"use client";
import React,{useState} from "react";import Link from "next/link";import api from "@/lib/api";
import {useResource,Table,Badge,Notice,button,date,message,panel} from "@/components/BillingUI";
interface Router{id:number;name:string;token:string;wgIp:string;wgPublicKey:string|null;cpuLoad:number;memoryUsage:number;status:string;lastSeen:string|null;uptime:string|null}
interface Task{id:number;action:string;status:string;createdAt:string}
export default function Page(){const {data,loading,error,load}=useResource<Router>("/api/routers",true);const [tab,setTab]=useState("ALL");const [selected,setSelected]=useState<Router|null>(null);const [tasks,setTasks]=useState<Task[]>([]);const [note,setNote]=useState("");const [command,setCommand]=useState("");
const open=async(r:Router)=>{setSelected(r);setCommand("");try{setTasks((await api.get<Task[]>(`/api/routers/${r.id}/tasks`)).data);}catch(e){setNote(message(e));}};
const action=async(r:Router,action:string)=>{try{await api.post(`/api/routers/${r.id}/tasks`,{action});setNote("Action queued. Applied status requires a successful router acknowledgement.");await open(r);}catch(e){setNote(message(e));}};
const remove=async(r:Router)=>{if(!confirm(`Delete ${r.name}? Payment history may prevent deletion.`))return;try{await api.delete(`/api/routers/${r.id}`);await load();setSelected(null);}catch(e){setNote(message(e));}};
const showCommand=(r:Router,install=false)=>{const url=`${window.location.origin}/api/router/provision/${r.token}${install?"/install-management.rsc":""}`;setCommand(`:do { /tool fetch url="${url}" dst-path=wb-setup.rsc; /import wb-setup.rsc } on-error={ :put "Setup failed. Check router logs." }`);};
return <div className="mx-auto max-w-7xl space-y-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><h1 className="text-2xl font-semibold text-slate-900">MikroTik routers</h1><p className="mt-2 text-sm text-slate-500">Link routers, review telemetry, and manage hotspot services.</p></div><Link href="/dashboard/routers/new" className={button}>Link a MikroTik</Link></div><Notice text={error||note}/><div className="flex gap-2">{["ALL","ONLINE","OFFLINE"].map(t=><button key={t} onClick={()=>setTab(t)} className={`rounded-lg border px-4 py-2 text-xs ${t===tab?"border-blue-200 text-blue-700":"border-slate-300 text-slate-500"}`}>{t} {data.filter(r=>t==="ALL"|| (t==="ONLINE"?r.status==="online":r.status!=="online")).length}</button>)}</div><Table rows={data.filter(r=>tab==="ALL"|| (tab==="ONLINE"?r.status==="online":r.status!=="online"))} loading={loading} columns={[{label:"Name",render:r=><button onClick={()=>open(r)} className="text-blue-700">{r.name}</button>},{label:"Provisioning",render:r=><Badge tone={r.wgPublicKey?"green":"amber"}>{r.wgPublicKey?"Key registered":"Awaiting router"}</Badge>},{label:"CPU",render:r=>r.lastSeen?`${r.cpuLoad||0}%`:"—"},{label:"Memory",render:r=>r.lastSeen?`${r.memoryUsage||0}%`:"—"},{label:"Status",render:r=><Badge tone={r.status==="online"?"green":"amber"}>{r.status}</Badge>},{label:"Tunnel IP",render:r=>r.wgIp||"Not allocated"},{label:"Last telemetry",render:r=>date(r.lastSeen)},{label:"Actions",render:r=><button onClick={()=>open(r)} className="text-blue-700">Manage</button>}]}/>
{selected&&<section className={`${panel} space-y-5 p-5`}><div className="flex justify-between"><h2 className="text-lg font-semibold text-slate-900">{selected.name}</h2><button onClick={()=>setSelected(null)} className="text-xs text-slate-500">Close</button></div><p className="text-xs leading-6 text-slate-500">WinBox over your routed WireGuard connection: <code className="text-blue-700">{selected.wgIp||"No tunnel IP"}:8291</code>. This is a private tunnel address, not a public remote-access endpoint.</p><div className="flex flex-wrap gap-3"><button onClick={()=>showCommand(selected,true)} className={button}>Install / repair management agent</button><button onClick={()=>action(selected,"SYNC_PORTAL")} className={button}>Sync hotspot files</button><button onClick={()=>action(selected,"SYNC_TIME")} className={button}>Sync router time</button><button onClick={()=>showCommand(selected)} className="text-xs text-amber-700">Reprovision command</button><button onClick={()=>open(selected)} className="text-xs text-blue-700">Refresh actions</button><button onClick={()=>remove(selected)} className="text-xs text-red-600">Delete router</button></div>{command&&<div><p className="mb-2 text-xs text-amber-700">Run this in the router terminal. Full reprovisioning moves customer interfaces; management-agent installation only enables sync and UTC/NTP time.</p><textarea aria-label="Router setup command" readOnly value={command} onFocus={e=>e.target.select()} className="h-24 w-full rounded-lg border border-slate-300 bg-[#0B1F36] p-3 font-mono text-xs text-slate-200"/><p className="mt-1 text-xs text-slate-500">Select the command and copy it. Keep this token private.</p></div>}<Table rows={tasks} columns={[{label:"Action",render:t=>t.action},{label:"Status",render:t=><Badge tone={t.status==="APPLIED"?"green":t.status==="FAILED"?"red":"amber"}>{t.status}</Badge>},{label:"Requested",render:t=>date(t.createdAt)}]}/></section>}</div>;
}
